WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pb_c_equal'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '等可能模型', 'kp-pb-c-equal', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "古典概型：等可能模型"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "扔硬币、掷骰子、抽扑克牌。每个结果出现的概率完全一样。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“抛掷两枚均匀的硬币，出现一正一反的概率是多少？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[先不看条件, 列出所有的可能性总数(分母)] --> B[再仔细看题干条件, 挑出满足条件的情况数(分子)]\nB --> C[分子 ÷ 分母]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 掷两枚骰子，点数之和为 7 的概率？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "总情况（分母）：第一枚 6 种，第二枚 6 种。6 × 6 = 36 种。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "满足条件（分子）：(1,6), (2,5), (3,4), (4,3), (5,2), (6,1)。共 6 种。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "结果：6 / 36 = 1/6。"}]}]}]}]}$$ AS jsonb), NULL, '等可能模型的核心考点与实战推导。', category_node.id, CAST('["数量关系", "概率问题", "等可能模型"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pb_c_equal", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
